def compute_sortino_on_bars(gross_pnl, intraday_returns, epsilon=1e-6):
    downside_variance = np.sum(np.minimum(intraday_returns, 0) ** 2)
    downside_deviation = np.sqrt(downside_variance)
    return gross_pnl / (downside_deviation + epsilon)

